 const authForm=<section className="auth-card" aria-labelledby="auth-title">{!mobileView&&<button className="auth-close" type="button" aria-label={lang==='ar'?'إغلاق':'Close'} disabled={authBusy} onClick={()=>setAuthOpen(false)}><X size={21}/></button>}<div className="auth-form-brand"><Logo/></div><div className="eyebrow">A SPACE FOR WHAT MATTERS</div><h2 id="auth-title">{mode==='register'?t.create:mode==='recover'?t.reset:t.welcome}</h2><p className="auth-subtitle">{t.private}</p><form onSubmit={authenticate} key={mode}>{mode==='register'&&<label>{t.name}<input name="name" autoComplete="name" maxLength={60} required placeholder={lang==='ar'?'كيف نناديك؟':'What should we call you?'}/></label>}<label>{t.email}<input name="email" dir="ltr" type="email" autoComplete="email" required maxLength={254} placeholder="you@example.com"/></label>{mode==='recover'&&<label>{t.code}<input name="code" dir="ltr" autoComplete="off" required placeholder="••••••••••••••••"/></label>}<label>{mode==='recover'?t.newPassword:t.password}<div className="password-input"><input name="password" dir="ltr" type={showPassword?'text':'password'} autoComplete={mode==='login'?'current-password':'new-password'} minLength={10} maxLength={128} required placeholder={t.minPassword}/><button type="button" onClick={()=>setShowPassword(!showPassword)} aria-label={showPassword?'Hide password':'Show password'}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></label>{error&&<div role="alert" className="error-message">{error}</div>}<button className="primary auth-submit" disabled={authBusy}>{authBusy?<Loader2 className="spin" size={19}/>:<>{mode==='register'?t.signup:mode==='recover'?t.reset:t.login}<ArrowUpRight size={18}/></>}</button></form><div className="auth-switch">{mode==='recover'?<button onClick={()=>{setMode('login');setError('')}}>{t.back}</button>:<>{mode==='register'?t.already:t.newHere} <button onClick={()=>{setMode(mode==='register'?'login':'register');setError('')}}>{mode==='register'?t.login:t.signup}</button></>}</div>{mode==='login'&&<button className="recovery-link" onClick={()=>{setMode('recover');setError('')}}>{t.recover}</button>}<div className="auth-security"><ShieldCheck size={15}/>{t.safe}</div></section>;
 const sidebarLabels=lang==='ar'?{dashboard:'لوحة التحكم',all:t.library,articles:'المقالات',snippets:'المقتطفات',favorites:t.favorites,archive:t.archive,trash:'المحذوفات'}:{dashboard:'Dashboard',all:t.library,articles:'Articles',snippets:'Code snippets',favorites:t.favorites,archive:t.archive,trash:'Trash'};
