 const collectionDepth=(record:Collection)=>{let depth=0,parent=record.parent_id;const seen=new Set<string>();while(parent&&!seen.has(parent)&&depth<20){seen.add(parent);const p=collectionRecords.find(x=>x.id===parent);if(!p)break;depth++;parent=p.parent_id}return depth};
 const renderCard=(item:Item,i:number)=><article draggable onDragStart={e=>e.dataTransfer.setData('application/x-oriva-item',item.id)} className="link-card" key={item.id} style={{animationDelay:Math.min(i,12)*25+'ms'}}><div className={'card-visual visual-'+(Math.abs(Array.from(domain(item.url)).reduce((a,c)=>a+c.charCodeAt(0),0))%5)}><div className="visual-orb"/><div className="visual-ring"/>{item.image?<img className="card-cover-image" src={'/api/images/'+item.image} alt={item.title} loading="lazy"/>:<span className="domain-monogram">{item.kind==='file'?<FileText size={52}/>:domain(item.url).slice(0,1).toUpperCase()}</span>}<span className="visual-domain">{item.kind==='article'?(lang==='ar'?'مقال':'Article'):item.kind==='snippet'?(item.language||'Code'):item.kind==='file'?extension(item.file_name)+' · '+fileSize(item.file_size):domain(item.url)}</span><span className="link-badge">{item.kind==='file'?<Download size={15}/>:<Link2 size={15}/>}</span><div className="card-actions"><button disabled={pendingItems.includes(item.id)} className={item.favorite?'is-favorite':''} aria-label={item.favorite?t.unfavorite:t.favorite} onClick={()=>change(item,{favorite:!item.favorite})}><Star size={16} fill={item.favorite?'currentColor':'none'}/></button><button aria-label={lang==='ar'?'المزيد':'More'} aria-expanded={cardMenu===item.id} onClick={()=>setCardMenu(cardMenu===item.id?'':item.id)}><MoreHorizontal size={19}/></button></div></div><div className="card-content"><a className="card-title" onClick={e=>{if(item.kind==='article'||item.kind==='snippet'){e.preventDefault();openItem(item)}}} href={item.kind==='article'||item.kind==='snippet'?'#':item.url} target={item.kind==='file'?undefined:'_blank'} rel="noopener noreferrer">{item.title}{item.kind==='file'?<Download size={16}/>:<ArrowUpRight size={16}/>}</a><p className="card-note">{item.note||(item.kind==='article'||item.kind==='snippet'?item.body.slice(0,180):item.kind==='file'?item.file_name+' · '+fileSize(item.file_size):domain(item.url))}</p>{item.tags.length>0&&<div className="tags">{item.tags.slice(0,3).map(tag=><button key={tag} onClick={()=>setQuery(tag)}>#{tag}</button>)}{item.tags.length>3&&<span>+{item.tags.length-3}</span>}</div>}<div className="card-footer"><span className={'status-label status-'+item.status}><i/>{t[item.status as keyof typeof t]}</span><span>{new Date(item.created*1000).toLocaleDateString(lang==='ar'?'ar-SA-u-ca-gregory':'en-US',{month:'short',day:'numeric'})}</span></div></div>{cardMenu===item.id&&<><button className="popover-dismiss" aria-label={lang==='ar'?'إغلاق':'Close'} onClick={()=>setCardMenu('')}/><div className="card-popover">{item.deleted_at?<button onClick={()=>change(item,{deleted:false} as Partial<Item>)}>{lang==='ar'?'استعادة من المحذوفات':'Restore from trash'}</button>:null}<button onClick={()=>change(item,{pinned:!item.pinned})}>{item.pinned?(lang==='ar'?'إلغاء التثبيت':'Unpin'):(lang==='ar'?'تثبيت':'Pin')}</button><button onClick={()=>openItem(item)}><Pencil size={15}/>{item.kind==='file'?(lang==='ar'?'تعديل الملف':'Edit file'):t.edit}</button><button onClick={()=>{copy(item.kind==='file'?new URL(item.url,window.location.origin).href:item.url);setCardMenu('')}}><Copy size={15}/>{t.copy}</button><button onClick={()=>change(item,{status:item.status==='archived'?'inbox':'archived'})}><Archive size={15}/>{item.status==='archived'?t.restore:t.moveArchive}</button><button className="danger-text" onClick={()=>{setDeleting(item);setCardMenu('')}}><Trash2 size={15}/>{item.kind==='file'?(lang==='ar'?'حذف الملف':'Delete file'):t.delete}</button></div></>}</article>;
